function remainingAt(route,p){if(!Array.isArray(route)||route.length<2)return null;const n=C.nearestPointOnRoute(route,[p.x,p.y]);if(!n||!Number.isFinite(n.distance))return null;return [[p.x,p.y],...route.slice(n.segmentIndex+1).map(q=>q.slice())];}
